before.pages.py:
def pages(items: list[int], size: int):
    if size <= 0:
        raise ValueError('size must be positive')
    for start in range(0, len(items), size):
        yield items[start:start + size]

after.pages.py:
def pages(items: list[int], size: int):
    if size <= 0:
        raise ValueError('size must be positive')
    for start in range(0, len(items) - size, size):
        yield items[start:start + size]

